  #edit-task-modal .modal-body,
  #add-event-modal .modal-body,
  #add-cr-notice-modal .modal-body {
    flex: 1;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
  }

  #add-task-modal .modal-footer,
  #edit-task-modal .modal-footer,
  #add-event-modal .modal-footer,
  #add-cr-notice-modal .modal-footer {
    flex-shrink: 0;
    position: sticky;
    bottom: 0;
    background: var(--bg-white);
    border-top: 2px solid var(--border-light);
    padding: var(--spacing-sm) var(--spacing-md);
  }

  /* Prevent browser auto-zoom on mobile inputs */
  .form-input,
  .form-select,
  .form-textarea {
    font-size: 16px !important;
  }

  /* Prevent body scroll when modal is open */
  body:has(#add-task-modal[style*="display: flex"]),
