// Reset (delete) all old tasks for a department/semester/section group (admin or CR)
async resetOldTasks(department, semester, section, includeNoDeadline = false) {
  try {
    const now = new Date();
    const sectionsInGroup = Utils.getSectionsInGroup(section);
    const snapshot = await db.collection('tasks')
      .where('department', '==', department)
      .where('semester', '==', semester)
      .where('section', 'in', sectionsInGroup)
      .get();

    const batch = db.batch();
    let deletedCount = 0;

    snapshot.forEach(doc => {
      const data = doc.data();
      if (!data.deadline) {
        // Check for auto-deletion after that semester (~180 days) or explicit Admin/CR reset
        const createdAt = data.createdAt ? (data.createdAt.toDate ? data.createdAt.toDate() : new Date(data.createdAt)) : null;
        const isOlderThanSemester = createdAt && ((now - createdAt) > 180 * 24 * 60 * 60 * 1000);
