async handleResetTasks() {
  if (!this.isAdmin && !this.isCR) return;

  // Check if there are tasks with no deadline in current group
  const noDeadlineCount = (this.currentTasks || []).filter(t => !t.deadline).length;
  let includeNoDeadline = false;

  let confirmMsg = 'Are you sure you want to reset all old/past tasks? This action cannot be undone.';
  if (noDeadlineCount > 0) {
    includeNoDeadline = confirm(`Found ${noDeadlineCount} task(s) without a deadline.\n\nClick OK to also delete these no-deadline tasks, or Cancel to keep them and only reset tasks with expired deadlines.`);
    confirmMsg = includeNoDeadline
      ? `Confirm: Reset past deadline tasks AND all ${noDeadlineCount} no-deadline tasks?`
      : 'Confirm: Reset only past tasks with expired deadlines?';
  }

  const confirmed = confirm(confirmMsg);
  if (!confirmed) return;

  const { department, semester, section } = this.userProfile;
  const result = await DB.resetOldTasks(department, semester, section, includeNoDeadline);

  if (result.success) {
    alert(`Successfully reset ${result.deletedCount} old tasks.`);
    await this.loadDashboardData();
  } else {
    alert('Failed to reset tasks: ' + result.error);
  }
},

