const fs = require('fs');
const path = require('path');

const dir = 'd:/GitHub/[oU1TS]/b1t-Sched/doc/prompts/36. Classroom Shortcut FAB, Navbar GitHub Button & Mobile Footer Icons';
const flatFile = 'd:/GitHub/[oU1TS]/b1t-Sched/doc/prompts/36. Classroom Shortcut FAB, Navbar GitHub Button & Mobile Footer Icons.md';
const summaryFile = path.join(dir, 'summary.md');

// 1. Update summary.md
let summary = fs.readFileSync(summaryFile, 'utf8');
if (!summary.includes('Turn 5')) {
  summary += `

---

## Turn 5: Desktop Floating "Browse as Visitor" Button

### Directives & Changes
- **Problem**: On desktop viewports, the "Browse as Visitor" button was taking up vertical space at the bottom of \`.auth-card\`, causing the card to overlap directly with the centered bouncing "FAQ & Support" scroll indicator (\`.login-scroll-indicator\`).
- **Solution**:
  1. Extracted \`#visitor-mode-btn\` from \`<form id=\"login-form\">\` to sit directly under the forms in \`.auth-card\`.
  2. Applied responsive desktop styling (\`@media (min-width: 769px)\`) transforming \`#visitor-mode-btn\` into a fixed bottom-right floating pill button (\`bottom: 24px; right: 28px; z-index: 95;\`) with elevation, hover animation, and Dark/Gray mode theme adaptation.
  3. Shortened \`.auth-card\` height on desktop, providing generous vertical clearance above the centered \`.login-scroll-indicator\` ("FAQ & Support").
  4. Preserved clean block button rendering on mobile viewports (\`<= 768px\`) while hiding on mobile signup mode.
`;
  fs.writeFileSync(summaryFile, summary, 'utf8');
}

// 2. Update flat prompt file
let flat = fs.readFileSync(flatFile, 'utf8');
if (!flat.includes('Turn 5:')) {
  flat += `

---

## Turn 5: Desktop Floating "Browse as Visitor" Button

### User Request
> make the "Browser as visitor" a right-bottom floating button for desktop since it is overlapping with "FAQ & Support" hint button.

### Implementation Summary
1. **Desktop Floating Pill Positioning**:
   - Styled \`#visitor-mode-btn\` on desktop viewports (\`@media (min-width: 769px)\`) as \`position: fixed; bottom: 24px; right: 28px; z-index: 95;\` with rounded pill borders (\`50px\`), card background, border, and elevation shadow.
   - Added hover state (\`transform: translateY(-2px)\`, accentuated shadow) and active state (\`translateY(0)\`).
   - Implemented custom Dark Mode and Gray Mode styles for seamless theme consistency.
2. **Eliminated "FAQ & Support" Collision**:
   - Because \`#visitor-mode-btn\` is removed from the normal layout flow on desktop, \`.auth-card\` height is reduced, creating substantial clearance above the centered \`.login-scroll-indicator\` ("FAQ & Support").
3. **Mobile & Viewport Scoping**:
   - On mobile screens (\`<= 768px\`), \`#visitor-mode-btn\` remains a natural full-width block button below the login form.
   - Automatically hidden on mobile when switching to \`#signup-form\`.
   - Naturally hidden whenever \`#login-view\` has \`display: none\` (after login or in visitor mode).
`;
  fs.writeFileSync(flatFile, flat, 'utf8');
}

// 3. Copy transcript_full.jsonl and regenerate conversation.md
const src = 'C:/Users/gsmur/.gemini/antigravity/brain/b72c1402-0b1e-42a7-a81f-3e22e5e1408d/.system_generated/logs/transcript_full.jsonl';
const transcriptPath = path.join(dir, 'transcript_full.jsonl');

fs.copyFileSync(src, transcriptPath);
const lines = fs.readFileSync(transcriptPath, 'utf8').trim().split('\n');

let md = '# Conversation Transcript - 36. Classroom Shortcut FAB, Navbar GitHub Button & Mobile Footer Icons\n\n';
md += '- **Conversation ID**: b72c1402-0b1e-42a7-a81f-3e22e5e1408d\n';
md += '- **Total Steps Recorded**: ' + lines.length + '\n\n---\n\n';

lines.forEach((l, i) => {
  if (!l.trim()) return;
  try {
    const obj = JSON.parse(l);
    md += '### Step ' + (obj.step_index !== undefined ? obj.step_index : i) + ' (' + (obj.source || 'UNKNOWN') + ' - ' + (obj.type || 'STEP') + ')\n';
    md += '*Created at: ' + (obj.created_at || 'N/A') + '*\n\n';
    if (obj.thinking) {
      md += '<details><summary>Thinking</summary>\n\n' + obj.thinking + '\n\n</details>\n\n';
    }
    if (obj.content) {
      md += '#### Content:\n' + obj.content + '\n\n';
