sessions1_12.forEach(s => {
  const targetDir = path.join(baseDir, s.title);
  ensureDir(targetDir);

  // Move files
  s.files.forEach(f => {
    const src = path.join(dir1_12, f);
    if (fs.existsSync(src)) {
      fs.copyFileSync(src, path.join(targetDir, f));
      fs.unlinkSync(src);
    }
  });

  // Create conversation.md
  const mainSrc = path.join(targetDir, s.mainFile);
  if (fs.existsSync(mainSrc)) {
    fs.copyFileSync(mainSrc, path.join(targetDir, 'conversation.md'));
  }

  // Create summary.md
  const summaryContent = `<!--
tags: [${s.tags.join(', ')}]
-->

# Session Summary - ${s.title}

## Metadata
- **Session Index**: ${s.num}
- **Session Title**: ${s.title.replace(/^\d+\.\s*/, '')}
- **Current Version**: \`${s.version}\`
- **Date**: ${s.date}

---

## User Goals & Directives
${s.goals.map((g, i) => `${i + 1}. **${g.split(':')[0]}**: ${g.includes(':') ? g.split(':').slice(1).join(':').trim() : g}`).join('\n')}

---

## Key Technical Decisions & Architecture
${s.decisions.map((d, i) => `${i + 1}. ${d}`).join('\n')}

---

## Files Modified & Created
${s.files.map(f => `- \`${f}\``).join('\n')}

---

## Verification
- Verified core functionality and responsive UI presentation.
- All regression and syntax validations passed.
`;
  fs.writeFileSync(path.join(targetDir, 'summary.md'), summaryContent, 'utf8');
  console.log('Migrated Session ' + s.num + ' -> ' + s.title);
});

