const fs = require('fs');
const path = require('path');

const dir36 = 'd:/GitHub/[oU1TS]/b1t-Sched/doc/prompts/36. Classroom Shortcut FAB, Navbar GitHub Button & Mobile Footer Icons';
const summaryFile = path.join(dir36, 'summary.md');
const flatFile = path.join(dir36, '36. Classroom Shortcut FAB, Navbar GitHub Button & Mobile Footer Icons.md');

// 1. Update summary.md
let summary = fs.readFileSync(summaryFile, 'utf8');
if (!summary.includes('Turn 9')) {
  summary += `

---

## Turn 9: Git Staging Verification & Continuity Check

### Status
- Confirmed repository clean staging state across all modified and newly reorganized prompt directories (Sessions 1 to 36).
- Validated all 36 session folders comply with AGENTS.md Rule 2 format and documentation standards.
- Ready to proceed with backlog implementation plan phases or assist with commit/push.
`;
  fs.writeFileSync(summaryFile, summary, 'utf8');
}

// 2. Update flat prompt file if exists
if (fs.existsSync(flatFile)) {
  let flat = fs.readFileSync(flatFile, 'utf8');
  if (!flat.includes('Turn 9:')) {
    flat += `

---

## Turn 9: Git Staging Verification & Continuity Check

### User Request
> continue

### Implementation Summary
- Verified all staged changes in Git index.
- Synchronized session 36 transcript and conversation logs.
`;
    fs.writeFileSync(flatFile, flat, 'utf8');
  }
}

// 3. Sync transcript_full.jsonl and regenerate conversation.md
const src = 'C:/Users/gsmur/.gemini/antigravity/brain/b72c1402-0b1e-42a7-a81f-3e22e5e1408d/.system_generated/logs/transcript_full.jsonl';
const transcriptPath = path.join(dir36, 'transcript_full.jsonl');

if (fs.existsSync(src)) {
  fs.copyFileSync(src, transcriptPath);
  const lines = fs.readFileSync(transcriptPath, 'utf8').trim().split('\n');

  let md = '# Conversation Transcript - 36. Classroom Shortcut FAB, Navbar GitHub Button & Mobile Footer Icons\n\n';
  md += '- **Conversation ID**: b72c1402-0b1e-42a7-a81f-3e22e5e1408d\n';
  md += '- **Total Steps Recorded**: ' + lines.length + '\n\n---\n\n';

  lines.forEach((l, i) => {
    if (!l.trim()) return;
    try {
      const obj = JSON.parse(l);
      md += '### Step ' + (obj.step_index !== undefined ? obj.step_index : i) + ' (' + (obj.source || 'UNKNOWN') + ' - ' + (obj.type || 'STEP') + ')\n';
      md += '*Created at: ' + (obj.created_at || 'N/A') + '*\n\n';
      if (obj.thinking) {
        md += '<details><summary>Thinking</summary>\n\n' + obj.thinking + '\n\n</details>\n\n';
      }
      if (obj.content) {
        md += '#### Content:\n' + obj.content + '\n\n';
      }
      if (obj.tool_calls && obj.tool_calls.length) {
        md += '#### Tool Calls:\n```json\n' + JSON.stringify(obj.tool_calls, null, 2) + '\n```\n\n';
      }
      md += '---\n\n';
    } catch (err) {
      md += '*(Parse error on line ' + i + ')*\n\n---\n\n';
    }
  });

  md += '## Pending Final Response (Pre-Commit)\n*(Will be finalized from transcript_full.jsonl on subsequent turn sync)*\n';
  fs.writeFileSync(path.join(dir36, 'conversation.md'), md, 'utf8');

  console.log('Turn 9 sync complete. Total steps:', lines.length);
}
